import * as E from './engine.js';
import {duplicateGroups} from './prepare-engine.js';

export function createPrepareVisuals({t,esc,label,val,fmt}) {
 const cell=(v,typed=false)=>E.missing(v)?`<span class="change-null">${t('空值','Empty')}</span>`:`<span class="change-value">${esc(typed&&typeof v==='string'?JSON.stringify(v):E.numeric(v)?fmt(v,4):val(v))}</span>`;
 const note=text=>`<p class="change-note">${text}</p>`;
 const pill=(text,kind='')=>`<span class="change-pill ${kind}">${esc(text)}</span>`;
 const phase=(before,head,content)=>`<section class="change-phase ${before?'before':'after'}"><div class="change-phase-head"><span>${before?t('处理前','Before'):t('处理后','After')}</span><b>${esc(head)}</b></div>${content}</section>`;
 const compare=(before,after)=>`<div class="change-compare">${before}<div class="change-arrow" aria-hidden="true">→</div>${after}</div>`;
 const total=(value,unit)=>`<div class="change-total"><strong>${fmt(value)}</strong><span>${esc(unit)}</span></div>`;
 const metric=(name,value,kind='')=>`<div class="change-metric ${kind}"><span>${esc(name)}</span><b>${fmt(value)}</b></div>`;
 const headline=(text,detail,kind='')=>`<div class="change-summary ${kind}"><span class="change-summary-mark" aria-hidden="true">${kind==='unchanged'?'✓':'↳'}</span><div><strong>${esc(text)}</strong><p>${esc(detail)}</p></div></div>`;
 const table=(heads,body,highlight=-1)=>`<div class="change-table-scroll"><table class="change-table"><thead><tr>${heads.map((h,i)=>`<th class="${i===highlight?'new-cell':''}">${esc(h)}</th>`).join('')}</tr></thead><tbody>${body.map(row=>`<tr>${row.map((v,i)=>`<td class="${i===highlight?'new-cell':''}">${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 const bar=(good,bad,goodLabel,badLabel)=>`<div class="change-count-legend"><span><i></i>${esc(goodLabel)} <b>${fmt(good)}</b></span><span><i class="bad"></i>${esc(badLabel)} <b>${fmt(bad)}</b></span></div><div class="change-count-bar" role="img" aria-label="${esc(goodLabel)} ${good}; ${esc(badLabel)} ${bad}"><span style="width:${good+bad?100*good/(good+bad):0}%"></span><i style="width:${good+bad?100*bad/(good+bad):0}%"></i></div>`;
 const sourceRow=i=>`<span class="change-row-number">#${i+1}</span>`;
 function missing(r) {
  const beforeMissing=r.before.reduce((n,row)=>n+Number(E.missing(row[r.key])),0),afterMissing=r.after.reduce((n,row)=>n+Number(E.missing(row[r.afterKey])),0),drop=r.draft.method==='drop';
  const before=phase(true,label(r.key),total(beforeMissing,t('个空值','empty cells'))+`<p class="change-record-count">${t('记录总数','Total rows')} ${fmt(r.before.length)}</p>`+bar(r.before.length-beforeMissing,beforeMissing,t('有值','Present'),t('空值','Empty')));
  const after=phase(false,label(r.afterKey),total(afterMissing,t('个空值','empty cells'))+`<p class="change-record-count">${t('记录总数','Total rows')} ${fmt(r.after.length)}</p>`+bar(r.after.length-afterMissing,afterMissing,t('有值','Present'),t('空值','Empty')));
  const title=r.noChange?t('当前字段没有缺失值','This field has no missing values'):drop?t(`删除 ${r.removedRows} 条缺失记录`,`Remove ${r.removedRows} rows with missing values`):t(`填补 ${r.changedCells} 个空值`,`Fill ${r.changedCells} empty cells`);
  const method={mean:t('字段均值','column mean'),median:t('字段中位数','column median'),custom:t('指定值','custom value')};
  const fill=r.indices.length&&!drop?r.after[r.indices[0]][r.afterKey]:null;
  const description=drop?t(`只删除“${label(r.key)}”为空的整条记录，其余记录保留。`,`Remove entire rows where ${label(r.key)} is missing; retain other rows.`):r.noChange?t('无需填补，当前设置不改变记录。','No filling is needed for these settings.'):t(`使用${method[r.draft.method]} ${E.numeric(fill)?fmt(fill,4):val(fill)} 填补，记录总数保持 ${r.before.length} 条。`,`Fill with the ${method[r.draft.method]} ${E.numeric(fill)?fmt(fill,4):val(fill)}; retain all ${r.before.length} rows.`);
  const context=r.beforeCols.find(k=>k!==r.key&&E.profile(r.before,[k])[0].type!=='number');
  const examples=r.indices.slice(0,6).map(i=>[sourceRow(i),...(context?[cell(r.before[i][context])]:[]),cell(r.before[i][r.key]),`<span class="cell-change-arrow">→</span>`,drop?pill(t('整行删除','Row removed'),'removed'):cell(r.after[i][r.afterKey])]);
  return headline(title,description,r.noChange?'unchanged':'')+compare(before,after)+(examples.length?`<div class="change-section-title"><h3>${t('实际变化记录','Changed source records')}</h3><span>${t(`展示 ${examples.length} / ${r.indices.length} 条`,`Showing ${examples.length} / ${r.indices.length}`)}</span></div>${table([t('原行号','Source row'),...(context?[label(context)]:[]),t('原值','Before'),'',t('处理结果','Result')],examples,examples[0].length-1)}`:'');
 }
 function duplicates(r) {
  const info=duplicateGroups(r.before,r.beforeCols),removed=r.removedRows;
  const before=phase(true,t('当前数据集','Working dataset'),total(r.before.length,t('条记录','records'))+bar(r.after.length,removed,t('保留记录','Retain'),t('重复记录','Duplicates')));
  const after=phase(false,t('去重结果','Deduplicated dataset'),total(r.after.length,t('条记录','records'))+bar(r.after.length,0,t('保留记录','Retained'),t('重复记录','Duplicates')));
  const shown=info.groups.slice(0,4),keys=r.beforeCols.slice(0,4);
  return headline(removed?t(`移除 ${removed} 条重复，保留 ${r.after.length} 条记录`,`Remove ${removed} duplicates; retain ${r.after.length} records`):t('没有重复记录','No duplicate records'),t(`按全部 ${r.beforeCols.length} 个字段比较，完全相同的记录保留首次出现的一条。`,`Compare all ${r.beforeCols.length} fields; retain the first occurrence of each identical record.`),removed?'':'unchanged')+(removed?compare(before,after):'')+(shown.length?`<div class="change-section-title"><h3>${t('重复记录对照','Duplicate record comparison')}</h3><span>${t(`共 ${info.groups.length} 组重复`,`Duplicate groups: ${info.groups.length}`)}</span></div><div class="duplicate-examples">${shown.map((g,j)=>`<section class="duplicate-example"><div class="duplicate-example-head"><b>${t('第','Group ')}${j+1}${t('组','')}</b><div>${pill(t(`保留 #${g.first+1}`,`Keep #${g.first+1}`),'kept')}${g.indices.slice(1,7).map(i=>pill(t(`删除 #${i+1}`,`Remove #${i+1}`),'removed')).join('')}${g.indices.length>7?pill('+'+(g.indices.length-7)):''}</div></div><div class="duplicate-values">${keys.map(k=>`<span><small>${esc(label(k))}</small>${cell(r.before[g.first][k])}</span>`).join('')}</div></section>`).join('')}</div>${note(t(`展示前 ${shown.length} 组及前 ${keys.length} 个字段；重复判断使用全部字段。`,`Showing the first ${shown.length} duplicate groups and ${keys.length} fields; duplicate detection uses every field.`))}`:`<div class="change-clean-state"><span>✓</span><div><b>${t(`全部 ${r.before.length} 条记录均保留`,`All ${r.before.length} records are retained`)}</b><p>${t('当前数据无需去重。','This dataset does not need deduplication.')}</p></div></div>`);
 }
 function rename(r) {
  const p=E.profile(r.before,[r.key])[0],q=E.profile(r.after,[r.afterKey])[0],type=c=>c.type==='number'?t('数值','Number'):c.type==='date'?t('日期','Date'):t('文本','Text');
  const context=r.beforeCols.find(k=>k!==r.key),examples=[...new Set([...r.indices.slice(0,2),...r.before.map((_,i)=>i)])].slice(0,4);
  const mini=(before)=>table([t('原行号','Source row'),...(context?[label(context)]:[]),before?r.key:r.afterKey],examples.map(i=>[sourceRow(i),...(context?[cell(r.before[i][context])]:[]),cell(before?r.before[i][r.key]:r.after[i][r.afterKey],true)]),2-Number(!context));
  const before=phase(true,r.key,`<div class="change-schema"><span class="change-field-chip">${p.type==='number'?'#':'Aa'}</span><strong>${esc(r.key)}</strong>${pill(type(p))}</div>${mini(true)}`);
  const after=phase(false,r.afterKey,`<div class="change-schema"><span class="change-field-chip">${q.type==='number'?'#':'Aa'}</span><strong>${esc(r.afterKey)}</strong>${pill(type(q))}</div>${mini(false)}`);
  return headline(r.renamed?t(`“${r.key}”更名为“${r.afterKey}”`,`Rename ${r.key} to ${r.afterKey}`):r.changedCells?t(`转换 ${r.changedCells} 个单元格的类型`,`Convert ${r.changedCells} cell values`):t('输入新名称即可预览更名','Enter a new name to preview the rename'),r.changedCells?t(`记录数 ${r.before.length} 条；类型转换改变 ${r.changedCells} 个值，失败的转换显示为空值。`,`${r.before.length} records; type conversion changes ${r.changedCells} values. Failed conversions become empty cells.`):t(`${r.before.length} 条记录的原始值保持一致，${r.renamed?'只更新所选字段名称。':'当前没有数据变化。'}`,`All ${r.before.length} records retain their values. ${r.renamed?'Only the selected field name changes.':'No changes in the current settings.'}`),r.noChange?'unchanged':'')+compare(before,after)+`<div class="change-small-metrics">${metric(t('记录数','Records'),r.after.length)}${metric(t('字段数','Fields'),r.afterCols.length)}${metric(t('发生值变化','Changed values'),r.changedCells)}</div>`;
 }
 function calculate(r) {
  const d=r.draft,op=d.op==='/'?'÷':d.op==='*'?'×':d.op==='-'?'−':'+',right=d.b==='__constant'?d.constant:label(d.b),stats=E.describe(r.after.map(row=>row[r.key])),invalid=r.after.flatMap((row,i)=>E.missing(row[r.key])?[i]:[]),examples=[...new Set([...r.before.map((_,i)=>i).slice(0,4),...invalid.slice(0,1)])];
  const before=phase(true,t('原始字段','Input fields'),total(r.beforeCols.length,t('个字段','fields'))+`<div class="change-input-fields">${pill(label(d.a))}${d.b!=='__constant'?pill(label(d.b)):pill(t('常数 ','Constant ')+d.constant)}</div>`);
  const after=phase(false,t('新增计算字段','Calculated field added'),total(r.afterCols.length,t('个字段','fields'))+`<div class="change-schema"><span class="change-field-chip">#</span><strong>${esc(r.key)}</strong>${pill(t('新增','New'),'kept')}</div>`);
  return headline(t(`新增“${r.key}”，${stats.count} 个有效结果`,`Add ${r.key}: ${stats.count} valid results`),t(`新增 1 列，原有 ${r.before.length} 条记录保留。${invalid.length} 条因缺失输入或无效运算，结果为空。`,`Add one column and retain all ${r.before.length} rows. ${invalid.length} results are empty because inputs are missing or the arithmetic is invalid.`))+compare(before,after)+`<div class="change-formula"><b>${esc(r.key)}</b><span>=</span><span>${esc(label(d.a))}</span><strong>${op}</strong><span>${esc(right)}</span></div><div class="change-section-title"><h3>${t('逐行计算结果','Row-by-row calculation')}</h3><span>${t('原值代入后直接得到新字段','Source values produce the new field')}</span></div>${table([t('原行号','Source row'),label(d.a),t('运算','Operator'),d.b==='__constant'?t('常数','Constant'):label(d.b),r.key],examples.map(i=>[sourceRow(i),cell(r.before[i][d.a]),`<b class="calculation-symbol">${op}</b>`,cell(d.b==='__constant'?Number(d.constant):r.before[i][d.b]),cell(r.after[i][r.key])]),4)}<div class="change-small-metrics">${metric(t('有效结果','Valid results'),stats.count,'positive')}${metric(t('空值结果','Empty results'),invalid.length)}${metric(t('原始记录数','Source records'),r.before.length)}</div>`;
 }
 return {render:r=>({missing,duplicates,rename,calculate}[r.mode](r))};
}
